$\begin{array}{l}

\mathrm{CH}_{2} \mathrm{OHCH}_{2} \mathrm{CH}_{2} \mathrm{CH}_{2} \mathrm{OH}+2 \mathrm{Na} \\

\longrightarrow \mathrm{NaOCH}_{2} \mathrm{CH}_{2} \mathrm{CH}_{2} \mathrm{CH}_{2} \mathrm{ONa}+2 \mathrm{H}

\end{array}$

